/**
 * Returns the hold and keeps it alive: the checkout page shows the hold while the customer fills in the
 * payment form, and should not lose the seats under them while they do.
 */
public HoldDocument get(String holdId) {
    var hold = store.hold(holdId).orElseThrow(() -> new NotFoundException("no hold " + holdId));
    Instant now = clock.instant();
    if (hold.expiresAt().isAfter(now)) {
        store.extend(hold.id(), policy.expiresAt(now));
    }
    return hold;
}

